<x-hris.table id="document-table" endpoint="/personnel-documents/data" filters :columns="[['key'=>'employee.name','label'=>'Employee'],['key'=>'document_type','label'=>'Type'],['key'=>'document_year','label'=>'Year'],['key'=>'period','label'=>'Period'],['key'=>'current_status','label'=>'Status']]" :actions="[['name'=>'details','label'=>'Details'],['name'=>'action','label'=>'Action']]"><x-hris.field name="document_year" label="Year" type="number" min="2000" max="2100" data-table-filter/><x-hris.field name="status" type="select" :options="['Submitted'=>'Submitted','Acknowledged'=>'Acknowledged','Returned'=>'Returned','Cancelled'=>'Cancelled']" data-table-filter/></x-hris.table>
<x-hris.modal id="document-modal" title="Upload personnel document"><form id="document-form" data-endpoint="/personnel-documents" enctype="multipart/form-data"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="document_type" type="select" :options="array_combine($types,$types)" required/><x-hris.field name="document_year" type="number" min="2000" max="2100" :value="now('Asia/Manila')->year" required/><x-hris.field name="period" type="select" :options="['annual'=>'Annual','first_semester'=>'First semester','second_semester'=>'Second semester','one_time'=>'One time']" required/><x-hris.field name="remarks" class="col-12" type="textarea"/><x-hris.field name="file" class="col-12" type="file" accept=".pdf,.jpg,.jpeg,.png" required/></div><p class="form-text mt-3">A corrected returned document becomes a new version of the same submission; earlier files and action history remain available.</p></div><div class="modal-footer"><button class="btn btn-primary">Submit document</button></div></form></x-hris.modal>
<x-hris.modal id="document-action" title="Document action"><form id="document-action-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="action" type="select" :options="auth()->user()->hasAbility('documents.manage') ? ['acknowledge'=>'HR acknowledge','return'=>'Return for correction'] : ['cancel'=>'Cancel my submission']" required/><x-hris.field name="reason" class="col-12" type="textarea"/></div></div><div class="modal-footer"><button class="btn btn-primary">Record action</button></div></form></x-hris.modal>
