@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#document-table'),action=document.querySelector('#document-action-form');HRIS.bindForm(document.querySelector('#document-form'),{success:()=>table.table.load()});HRIS.bindForm(action,{success:()=>table.table.load()});table.addEventListener('table:action',({detail:{action:kind,row}})=>{if(kind==='details')HRIS.showDetails('Personnel document and history',row);else{HRIS.fillForm(action,{});action.dataset.endpoint=`/personnel-documents/${row.id}/transition`;HRIS.openModal('document-action')}})});</script>@endpush
